/* Hentai Hub for Nuvio - all (generated by build.js, edit src/ instead) */
/* ====================================================================
 *  SHARED LIB  (di-inject otomatis ke setiap providers/*.js oleh build.js)
 *  Aturan Nuvio: Hermes engine, pakai fetch + Promise (.then), tanpa npm.
 * ==================================================================== */
var UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';

// >>> ISI DI SINI: API key TMDB gratis (https://www.themoviedb.org/settings/api)
// Boleh v3 key (32 karakter) atau v4 "API Read Access Token" (panjang, diawali eyJ)
var TMDB_API_KEY = '';

var TIMEOUT_MS = 25000; // NuvioTV membatasi ~30 detik per request provider

function log(tag, msg) { try { console.log('[' + tag + '] ' + msg); } catch (e) {} }
function flatten(arr) { var o = []; for (var i = 0; i < arr.length; i++) for (var j = 0; j < arr[i].length; j++) o.push(arr[i][j]); return o; }
function uniq(arr) { var s = {}, o = []; for (var i = 0; i < arr.length; i++) { if (arr[i] && !s[arr[i]]) { s[arr[i]] = 1; o.push(arr[i]); } } return o; }

/* ---------- HTTP ---------- */
function request(url, opts) {
  opts = opts || {};
  var headers = Object.assign({ 'User-Agent': UA, 'Accept-Language': 'en-US,en;q=0.9' }, opts.headers || {});
  return fetch(url, { method: opts.method || 'GET', headers: headers, body: opts.body, redirect: 'follow' })
    .then(function (r) {
      if (r.status >= 400) throw new Error('HTTP ' + r.status + ' ' + url);
      return r.text();
    });
}
function requestJson(url, opts) { return request(url, opts).then(function (t) { return JSON.parse(t); }); }

/* ---------- string utils ---------- */
function decodeHtml(s) {
  return String(s || '').replace(/&amp;/g, '&').replace(/&#0?39;|&#8217;|&rsquo;/g, "'").replace(/&quot;|&#8220;|&#8221;/g, '"').replace(/&#8211;|&ndash;/g, '-').replace(/&nbsp;/g, ' ');
}
function stripTags(s) { return decodeHtml(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(); }
function norm(s) { return decodeHtml(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function stripEp(s) { return String(s || '').replace(/\b(?:episode|ep|eps)\.?\s*\d+.*$/i, '').replace(/\s*[-:]\s*\d+\s*$/, ''); }
var STOP = { the: 1, a: 1, an: 1, of: 1, and: 1, hd: 1, uncensored: 1, ova: 1, ona: 1, subbed: 1, sub: 1, dub: 1, dubbed: 1, english: 1, hentai: 1 };
function tokens(s) { return norm(stripEp(s)).split(' ').filter(function (t) { return t && !STOP[t]; }); }
function similarity(a, b) {
  var ta = tokens(a), tb = tokens(b);
  if (!ta.length || !tb.length) return 0;
  var A = ta.join(' '), B = tb.join(' ');
  if (A === B) return 1;
  var inter = 0, i;
  for (i = 0; i < ta.length; i++) if (tb.indexOf(ta[i]) >= 0) inter++;
  var jac = inter / (ta.length + tb.length - inter);
  if (A.indexOf(B) >= 0 || B.indexOf(A) >= 0) jac = Math.max(jac, 0.85);
  return jac;
}
// cands: [{title,url}] ; titles: [string] -> kandidat terbaik (skor >= min)
function bestMatch(cands, titles, min) {
  var best = null, bs = 0;
  for (var i = 0; i < cands.length; i++) {
    for (var j = 0; j < titles.length; j++) {
      var sc = similarity(cands[i].title, titles[j]);
      if (sc > bs) { bs = sc; best = cands[i]; }
    }
  }
  return bs >= (min || 0.6) ? best : null;
}
function attr(tag, name) {
  var m = new RegExp('\\b' + name + '\\s*=\\s*["\']([^"\']*)["\']', 'i').exec(tag);
  return m ? decodeHtml(m[1]) : '';
}
function originOf(u) { var m = /^(https?:\/\/[^\/?#]+)/i.exec(u || ''); return m ? m[1] : ''; }
function abs(u, base) {
  u = decodeHtml(u || '').trim();
  if (!u) return '';
  if (/^https?:\/\//i.test(u)) return u;
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.charAt(0) === '/') return originOf(base) + u;
  return base.replace(/[^\/]*$/, '') + u;
}
function epNumber(s) {
  var m = /(?:episode|ep|eps)[\s._-]*0*(\d+)/i.exec(s || '') || /-0*(\d+)\/?(?:[?#].*)?$/.exec(s || '');
  return m ? parseInt(m[1], 10) : null;
}

/* ---------- parsing ---------- */
// Ambil semua <a href> yang cocok pathRe -> [{url,title}]
function parseLinks(html, base, pathRe) {
  var re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi, m, map = {}, order = [];
  while ((m = re.exec(html))) {
    var href = abs(attr(m[1], 'href'), base);
    if (!href || !pathRe.test(href)) continue;
    href = href.replace(/#.*$/, '');
    var imgAlt = /<img[^>]*\balt=["']([^"']+)["']/i.exec(m[2]);
    var title = attr(m[1], 'title') || stripTags(m[2]) || (imgAlt ? decodeHtml(imgAlt[1]) : '');
    if (!map[href]) { map[href] = ''; order.push(href); }
    if (title.length > map[href].length) map[href] = title;
  }
  return order.map(function (u) { return { url: u, title: map[u] }; }).filter(function (c) { return c.title; });
}

var BAD_URL = /\.(jpe?g|png|gif|webp|svg|css|js|ico|woff2?|vtt|srt)(\?|$)|wp-json|wp-content|gravatar|google|facebook|twitter|schema\.org|w\.org|sample|big_?buck|test-streams/i;
function extractLinks(text) {
  var s = String(text).replace(/\\\//g, '/').replace(/&amp;/g, '&'), re = /https?:\/\/[^"'\s<>\\)]+/g, m, out = [];
  while ((m = re.exec(s))) if (!BAD_URL.test(m[0])) out.push(m[0]);
  return uniq(out);
}

// p.a.c.k.e.d unpacker (banyak embed player pakai ini)
function unpack(src) {
  if (src.indexOf('eval(function(p,a,c,k,e') < 0) return null;
  var m = /\}\('((?:[^'\\]|\\.)*)',\s*(\d+),\s*(\d+),\s*'((?:[^'\\]|\\.)*)'\.split\('\|'\)/.exec(src);
  if (!m) return null;
  var p = m[1], a = parseInt(m[2], 10), c = parseInt(m[3], 10), k = m[4].split('|');
  function e(n) { return (n < a ? '' : e(parseInt(n / a, 10))) + ((n = n % a) > 35 ? String.fromCharCode(n + 29) : n.toString(36)); }
  var d = {};
  while (c--) d[e(c)] = k[c] || e(c);
  return p.replace(/\b\w+\b/g, function (w) { return d[w] || w; }).replace(/\\'/g, "'");
}

function extractMedia(text) {
  var s = String(text).replace(/\\\//g, '/').replace(/&amp;/g, '&');
  var un = unpack(s);
  if (un) s += '\n' + un.replace(/\\\//g, '/');
  var re = /https?:\/\/[^"'\s<>\\)]+?\.(?:m3u8|mp4)(?:\?[^"'\s<>\\)]*)?/gi, m, out = [];
  while ((m = re.exec(s))) if (!BAD_URL.test(m[0])) out.push(m[0]);
  return uniq(out);
}
function isDirect(u) { return /\.(m3u8|mp4)(\?|#|$)/i.test(u); }

// Kumpulkan kandidat (iframe / video / link media) dari sebuah halaman
function collectFromPage(html, pageUrl) {
  var c = [], re = /<(?:iframe|source|video)\b([^>]*)>/gi, m;
  while ((m = re.exec(html))) {
    var src = abs(attr(m[1], 'src') || attr(m[1], 'data-src') || attr(m[1], 'data-lazy-src'), pageUrl);
    if (src && !BAD_URL.test(src)) c.push(src);
  }
  return uniq(c.concat(extractMedia(html)));
}

// URL embed/direct -> [{url, referer}] (hanya direct m3u8/mp4; Nuvio tidak memutar iframe)
function resolveEmbed(url, referer, depth) {
  depth = depth || 0;
  if (isDirect(url)) return Promise.resolve([{ url: url, referer: referer }]);
  if (depth > 1) return Promise.resolve([]);
  return request(url, { headers: { Referer: referer } }).then(function (html) {
    var media = extractMedia(html);
    if (media.length) return media.map(function (u) { return { url: u, referer: url }; });
    var ifr = [], re = /<iframe[^>]+src=["']([^"']+)["']/gi, m;
    while ((m = re.exec(html))) ifr.push(abs(m[1], url));
    return Promise.all(uniq(ifr).slice(0, 3).map(function (u) {
      return resolveEmbed(u, url, depth + 1).catch(function () { return []; });
    })).then(flatten);
  }).catch(function () { return []; });
}
function resolveAll(cands, referer) {
  return Promise.all(uniq(cands).slice(0, 8).map(function (u) {
    return resolveEmbed(u, referer).catch(function () { return []; });
  })).then(flatten);
}

/* ---------- TMDB ---------- */
function getTmdbInfo(tmdbId, mediaType, cfg) {
  var key = (cfg && cfg.tmdbApiKey) || TMDB_API_KEY;
  if (!key) return Promise.reject(new Error('TMDB_API_KEY kosong (isi di src/lib.js lalu build ulang)'));
  var kind = mediaType === 'movie' ? 'movie' : 'tv';
  var url = 'https://api.themoviedb.org/3/' + kind + '/' + tmdbId + '?append_to_response=alternative_titles';
  var opts = {};
  if (key.length > 40) opts.headers = { Authorization: 'Bearer ' + key }; else url += '&api_key=' + key;
  return requestJson(url, opts).then(function (d) {
    var t = [d.title, d.name, d.original_title, d.original_name];
    var alt = (d.alternative_titles && (d.alternative_titles.titles || d.alternative_titles.results)) || [];
    for (var i = 0; i < alt.length; i++) t.push(alt[i].title);
    var y = String(d.release_date || d.first_air_date || '').slice(0, 4);
    return { titles: uniq(t).slice(0, 12), year: y, tmdbId: tmdbId };
  });
}

// Coba search satu per satu sampai ada match. searchFn(q) -> Promise<[{title,url}]>
function findMatch(searchFn, titles, min) {
  var tries = titles.slice(0, 4), idx = 0;
  function next() {
    if (idx >= tries.length) return Promise.resolve(null);
    var q = tries[idx++];
    return searchFn(q).then(function (c) { return bestMatch(c, titles, min) || next(); }).catch(function (e) { log('search', e.message); return next(); });
  }
  return next();
}

/* ---------- output ---------- */
function guessQuality(u) {
  var m = /(\d{3,4})p/i.exec(u) || /[_-](\d{3,4})\.(?:mp4|m3u8)/i.exec(u);
  return m ? m[1] + 'p' : 'Auto';
}
function toStream(prov, info, it) {
  var ref = it.referer || prov.referer || '';
  var h = { 'User-Agent': UA };
  if (ref) { h.Referer = ref; h.Origin = originOf(ref); }
  return {
    name: prov.name + (it.label ? ' - ' + it.label : ''),
    title: info.titles[0] + (info.year ? ' (' + info.year + ')' : ''),
    url: it.url,
    quality: it.quality || guessQuality(it.url),
    headers: h,
    provider: prov.id
  };
}

// providers: [{id,name,run(info,mediaType,season,episode)->Promise<[{url,referer,label,quality}]>}]
function makeGetStreams(providers) {
  return function getStreams(tmdbId, mediaType, season, episode, userConfig) {
    var acc = [], seen = {};
    var job = getTmdbInfo(tmdbId, mediaType, userConfig).then(function (info) {
      log('hub', 'titles: ' + info.titles.slice(0, 3).join(' | '));
      return Promise.all(providers.map(function (p) {
        return p.run(info, mediaType, season, episode).then(function (items) {
          log(p.id, items.length + ' direct link(s)');
          items.forEach(function (it) {
            if (!it.url || seen[it.url]) return;
            seen[it.url] = 1;
            acc.push(toStream(p, info, it));
          });
        }).catch(function (e) { log(p.id, 'error: ' + e.message); });
      }));
    }).catch(function (e) { log('hub', e.message); });
    var timer = new Promise(function (res) { setTimeout(res, TIMEOUT_MS); });
    return Promise.race([job, timer]).then(function () { return acc.slice(); });
  };
}

// @var Hanime
// Situs: hanime.tv (JSON API). EKSPERIMENTAL: endpoint & proteksi sering berubah (Cloudflare / signature).
var Hanime = (function () {
  var SEARCH_URL = 'https://search.htv-services.com/search'; // <-- ganti kalau endpoint pindah
  var VIDEO_API = 'https://hanime.tv/api/v8/video?id='; // <-- ganti kalau endpoint pindah
  var SITE = 'https://hanime.tv/';
  var H = { Referer: SITE, Origin: 'https://hanime.tv', Accept: 'application/json' };

  function search(q) {
    var body = JSON.stringify({
      search_text: q, tags: [], tags_mode: 'AND', brands: [], blacklist: [],
      order_by: 'created_at_unix', ordering: 'desc', page: 0
    });
    return requestJson(SEARCH_URL, { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, H), body: body })
      .then(function (d) {
        var hits = typeof d.hits === 'string' ? JSON.parse(d.hits) : (d.hits || []);
        return hits.map(function (h) { return { title: h.name, url: h.slug }; });
      });
  }
  function video(slug) { return requestJson(VIDEO_API + encodeURIComponent(slug), { headers: H }); }

  function streamsOf(d) {
    var servers = (d.videos_manifest && d.videos_manifest.servers) || [], out = [];
    servers.forEach(function (s) {
      (s.streams || []).forEach(function (st) {
        if (st.url) out.push({ url: st.url, referer: SITE, label: s.name || '', quality: st.height ? st.height + 'p' : undefined, h: st.height || 0 });
      });
    });
    out.sort(function (a, b) { return b.h - a.h; });
    return out;
  }

  function run(info, mediaType, season, episode) {
    return findMatch(search, info.titles).then(function (hit) {
      if (!hit) return [];
      return video(hit.url).then(function (d) {
        var fr = d.hentai_franchise_hentai_videos || [], slug = hit.url;
        if (mediaType !== 'movie' && episode && fr.length > 1) {
          var n = Number(episode), found = null, i;
          for (i = 0; i < fr.length; i++) if (epNumber(fr[i].slug) === n) { found = fr[i]; break; }
          if (!found && fr[n - 1]) found = fr[n - 1];
          if (found && found.slug !== slug) slug = found.slug;
        }
        return slug === hit.url ? streamsOf(d) : video(slug).then(streamsOf);
      });
    });
  }

  return { id: 'hanime', name: 'Hanime', referer: SITE, run: run };
})();

// @var HentaiMama
// Situs: DooPlay (WordPress). Alur: search -> halaman series -> halaman episode -> player (ajax/iframe) -> m3u8/mp4
var HentaiMama = (function () {
  var BASE = 'https://hentaimama.io'; // <-- ganti di sini kalau domain pindah

  function search(q) {
    return request(BASE + '/?s=' + encodeURIComponent(q)).then(function (html) {
      return parseLinks(html, BASE, /\/(?:tvshows|movies|episodes)\/[^\/?#]+/i);
    });
  }

  // Ambil link embed dari tombol player DooPlay
  function dooPlayers(html, pageUrl) {
    var opts = [], re = /<li\b[^>]*dooplay_player_option[^>]*>/gi, m;
    while ((m = re.exec(html))) {
      opts.push({ post: attr(m[0], 'data-post'), nume: attr(m[0], 'data-nume') || '1', type: attr(m[0], 'data-type') || 'tv' });
    }
    return Promise.all(opts.map(function (o) {
      var rest = BASE + '/wp-json/dooplayer/v2/' + o.post + '/' + o.type + '/' + o.nume;
      return request(rest, { headers: { Referer: pageUrl } })
        .then(extractLinks)
        .then(function (l) { return l.length ? l : Promise.reject(new Error('empty')); })
        .catch(function () {
          return request(BASE + '/wp-admin/admin-ajax.php', {
            method: 'POST',
            headers: { 'X-Requested-With': 'XMLHttpRequest', 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', Referer: pageUrl, Origin: BASE },
            body: 'action=doo_player_ajax&post=' + o.post + '&nume=' + o.nume + '&type=' + o.type
          }).then(extractLinks);
        })
        .catch(function () { return []; });
    })).then(flatten);
  }

  function pickEpisode(page, pageUrl, mediaType, episode) {
    if (/\/episodes\//i.test(pageUrl)) {
      // hasil search langsung berupa halaman episode: sesuaikan nomor episode lewat URL
      if (mediaType === 'movie' || !episode || epNumber(pageUrl) === Number(episode)) return pageUrl;
      return pageUrl.replace(/(episode-)0*\d+/i, '$1' + episode);
    }
    var eps = parseLinks(page, BASE, /\/episodes\/[^\/?#]+/i);
    if (!eps.length) return null;
    if (mediaType === 'movie' || !episode) return eps[eps.length - 1].url;
    for (var i = 0; i < eps.length; i++) if (epNumber(eps[i].url) === Number(episode)) return eps[i].url;
    return eps.length === 1 ? eps[0].url : null;
  }

  function run(info, mediaType, season, episode) {
    return findMatch(search, info.titles).then(function (hit) {
      if (!hit) return [];
      return request(hit.url).then(function (page) {
        var epUrl = pickEpisode(page, hit.url, mediaType, episode);
        if (!epUrl) return [];
        var load = epUrl === hit.url ? Promise.resolve(page) : request(epUrl);
        return load.then(function (html) {
          return dooPlayers(html, epUrl).then(function (links) {
            return resolveAll(links.concat(collectFromPage(html, epUrl)), epUrl);
          });
        });
      });
    });
  }

  return { id: 'hentaimama', name: 'HentaiMama', referer: BASE + '/', run: run };
})();

// @var HentaiTV
// Situs: WordPress. Tiap episode = 1 halaman /hentai/<slug>-episode-N/. Alur: search -> pilih episode -> player -> m3u8/mp4
var HentaiTV = (function () {
  var BASE = 'https://hentai.tv'; // <-- ganti di sini kalau domain pindah

  function search(q) {
    return request(BASE + '/?s=' + encodeURIComponent(q)).then(function (html) {
      return parseLinks(html, BASE, /\/hentai\/[^\/?#]+\/?$/i);
    });
  }

  function run(info, mediaType, season, episode) {
    var all = [];
    function searchKeep(q) { return search(q).then(function (c) { all = all.concat(c); return c; }); }

    return findMatch(searchKeep, info.titles).then(function (hit) {
      if (!hit) return [];
      var pick = hit;
      if (mediaType !== 'movie' && episode) {
        // dari semua hasil search, ambil yang judulnya mirip DAN nomor episodenya cocok
        var sameSeries = all.filter(function (c) { return bestMatch([c], info.titles, 0.6); });
        for (var i = 0; i < sameSeries.length; i++) {
          if (epNumber(sameSeries[i].url) === Number(episode) || epNumber(sameSeries[i].title) === Number(episode)) { pick = sameSeries[i]; break; }
        }
        if (epNumber(pick.url) !== Number(episode) && epNumber(pick.title) !== Number(episode)) {
          var guess = pick.url.replace(/(episode-)0*\d+/i, '$1' + episode);
          if (guess !== pick.url) pick = { url: guess, title: pick.title };
        }
      }
      return request(pick.url).then(function (html) {
        return resolveAll(collectFromPage(html, pick.url), pick.url);
      });
    });
  }

  return { id: 'hentaitv', name: 'Hentai.TV', referer: BASE + '/', run: run };
})();

var getStreams = makeGetStreams([Hanime, HentaiMama, HentaiTV]);
if (typeof module !== 'undefined' && module.exports) { module.exports = { getStreams: getStreams }; }
if (typeof global !== 'undefined') { global.getStreams = getStreams; }
